import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 300;
    static final int INF = (int) 1e9;
    static class Edge {
        int to, rev, f, cap;
        Edge(int to, int rev, int f, int cap) {
            this.to = to;
            this.rev = rev;
            this.f = f;
            this.cap = cap;
        }
    }
    static List<Edge>[] adj = new ArrayList[MAXN];
    static int[] dis = new int[MAXN];
    static int[] ptr = new int[MAXN];
    static int src, dst;

    static boolean bfs() {
        Arrays.fill(dis, -1);
        dis[src] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(src);
        while(!q.isEmpty() && dis[dst] == -1) {
            int u = q.poll();
            for (Edge e : adj[u]) {
                int v = e.to;
                if (dis[v] == -1 && e.f < e.cap) {
                    dis[v] = dis[u] + 1;
                    q.add(v);
                }
            }
        }
        return dis[dst] != -1;
    }

    static int dfs(int u, int f) {
        if (u == dst || f == 0)
            return f;
        for (; ptr[u] < adj[u].size(); ptr[u]++) {
            Edge e = adj[u].get(ptr[u]);
            int v = e.to;
            if (dis[v] != dis[u] + 1)
                continue;
            int df = dfs(v, Math.min(f, e.cap - e.f));
            if (df > 0) {
                e.f += df;
                adj[v].get(e.rev).f -= df;
                return df;
            }
        }
        return 0;
    }

    static int mf() {
        int res = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int df;
            while((df = dfs(src, INF)) > 0)
                res += df;
        }
        return res;
    }

    static int[] dx = {-1, 0, 0, 1};
    static int[] dy = {0, -1, 1, 0};
    static int n, m;
    static List<List<Integer>> obs, tim, dii;
    static List<String> lab = new ArrayList<>();
    static List<String> rea = new ArrayList<>();

    static class Pair {
        int first, second;
        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static void gbfs(int r, int c, List<List<Integer>> dis, boolean chk) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                dis.get(i).set(j, -1);
        dis.get(r).set(c, 0);
        Queue<Pair> q = new ArrayDeque<>();
        q.add(new Pair(r, c));
        while (!q.isEmpty()) {
            Pair p = q.poll();
            int pr = p.first;
            int pc = p.second;
            if (chk && dis.get(pr).get(pc) == tim.get(pr).get(pc))
                continue;
            for (int i = 0; i < 4; i++) {
                int nr = pr + dx[i];
                int nc = pc + dy[i];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n || dis.get(nr).get(nc) != -1 || obs.get(nr).get(nc))
                    continue;
                if (chk && tim.get(nr).get(nc) > -1 && dis.get(pr).get(pc) + 1 > tim.get(nr).get(nc))
                    continue;
                dis.get(nr).set(nc, dis.get(pr).get(pc) + 1);
                q.add(new Pair(nr, nc));
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        for (int i = 0; i < MAXN; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            String rowLab = br.readLine();
            String rowRea = br.readLine();
            lab.add(rowLab);
            rea.add(rowRea);
        }
        obs = new ArrayList<>();
        tim = new ArrayList<>();
        dii = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> obsRow = new ArrayList<>();
            List<Integer> timRow = new ArrayList<>();
            List<Integer> diiRow = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                obsRow.add(lab.get(i).charAt(j) == 'Y' ? 1 : 0);
                timRow.add(-1);
                diiRow.add(-1);
            }
            obs.add(obsRow);
            tim.add(timRow);
            dii.add(diiRow);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (lab.get(i).charAt(j) == 'Z') {
                    gbfs(i, j, tim, false);
                }
            }
        }
        src = 2 * n * n + 5;
        dst = src + 1;

        int INF_int = INF;
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                char cellChar = lab.get(x).charAt(y);
                if (cellChar == 'Z' || cellChar == 'Y')
                    continue;
                addEdge(src, n * x + y, cellChar - '0');
                addEdge(n * n + n * x + y, dst, rea.get(x).charAt(y) - '0');
                gbfs(x, y, dii, true);
                for (int xp = 0; xp < n; xp++) {
                    for (int yp = 0; yp < n; yp++) {
                        if (dii.get(xp).get(yp) != -1 && dii.get(xp).get(yp) <= m) {
                            addEdge(n * x + y, n * n + n * xp + yp, INF_int);
                        }
                    }
                }
            }
        }
        System.out.println(mf());
    }

    static void addEdge(int u, int v, int c) {
        addEdge(u, v, c, 0);
    }

    static void addEdge(int u, int v, int c, int rc) {
        Edge a = new Edge(v, adj[v].size(), 0, c);
        Edge b = new Edge(u, adj[u].size(), 0, rc);
        adj[u].add(a);
        adj[v].add(b);
    }
